const result = params.verificar_identidad || {};
const ok = result.ok === true;
const verificado = ok && result.verificado === true;
const hasConditions = Boolean(result.condiciones && typeof result.condiciones === 'object' && !Array.isArray(result.condiciones));
const speech = hasConditions ? result.condiciones.speech : null;
const spokenString = (value) => typeof value === 'string' && value.trim().length > 0;
const hasSpeech = Boolean(speech && typeof speech === 'object' && !Array.isArray(speech) && ['initialPayment', 'installmentAmount', 'installmentCount', 'firstDueDate'].every((key) => spokenString(speech[key])) && Array.isArray(speech.installmentAmounts) && speech.installmentAmounts.length > 0 && speech.installmentAmounts.every(spokenString));
const complete = !verificado || (hasConditions && hasSpeech);
module.exports = {
  ok: ok && complete,
  verificado: verificado && hasConditions && hasSpeech,
  condiciones: verificado && hasConditions && hasSpeech ? result.condiciones : null,
  code: ok && complete ? null : 'IDENTITY_UNAVAILABLE'
};
